import{_ as t,o as a,c as o,a9 as r}from"./chunks/framework.asyjyako.js";const p=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md","lastUpdated":null}'),i={name:"guide/overview.md"};function n(s,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="Overview" tabindex="-1">Overview <a class="header-anchor" href="#Overview" aria-label="Permalink to &quot;Overview {#Overview}&quot;">​</a></h1><p>PerfChecker answers four different questions that are often mixed together:</p><ol><li><p><strong>What is being measured?</strong> A stable business feature and a representative workload.</p></li><li><p><strong>How is it measured?</strong> A benchmark, allocation tracker, profiler, network collector, or provider.</p></li><li><p><strong>Which implementation is measured?</strong> A release, working tree, branch, tag, commit, or Julia runtime.</p></li><li><p><strong>How is evidence consumed?</strong> A CI gate, interactive plot, report, documentation block, human review, or agent workflow.</p></li></ol><p>Keeping these axes independent is the central design rule. A feature such as <code>import_bibtex</code> should not be duplicated into names such as <code>import_bibtex_allocations</code> and <code>import_bibtex_profile</code> in the user interface. Those are check types attached to one feature.</p><h2 id="Find-your-way-through-the-documentation" tabindex="-1">Find your way through the documentation <a class="header-anchor" href="#Find-your-way-through-the-documentation" aria-label="Permalink to &quot;Find your way through the documentation {#Find-your-way-through-the-documentation}&quot;">​</a></h2><p>Start with <strong>Installation</strong>, then <strong>Your first result</strong>: a downloadable test item, one execution and its output. <strong>Suites and comparisons</strong> explains how to group workloads and compare versions. <strong>Measurements</strong> explains the numbers and tools. <strong>Interfaces</strong> lets you choose where to run and inspect those same experiments.</p><p>Once the local example works, use <strong>Automation and hosting</strong> to repeat it in CI. <strong>Advanced experiments</strong> adds runtime and machine comparisons. <strong>Optional advice</strong> is a separate path; no model is needed to follow any of the tutorials. <strong>Contracts and API</strong> is a lookup reference, not a prerequisite reading sequence.</p><h2 id="Execution-model" tabindex="-1">Execution model <a class="header-anchor" href="#Execution-model" aria-label="Permalink to &quot;Execution model {#Execution-model}&quot;">​</a></h2><p>PerfChecker has a controller/worker boundary:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Component</th><th style="text-align:right;">Responsibilities</th><th style="text-align:right;">Included in measurements?</th></tr></thead><tbody><tr><td style="text-align:right;">Controller</td><td style="text-align:right;">Resolve versions, build plans, schedule jobs, write reports, serve UIs</td><td style="text-align:right;">No</td></tr><tr><td style="text-align:right;">Malt worker</td><td style="text-align:right;">Load one target, one workload and one collector</td><td style="text-align:right;">Yes</td></tr><tr><td style="text-align:right;">Reporter</td><td style="text-align:right;">Convert bundles into tables, plots, documentation and CI evidence</td><td style="text-align:right;">No</td></tr><tr><td style="text-align:right;">Oxygen agent</td><td style="text-align:right;">Lease work from a controller and launch local isolated workers</td><td style="text-align:right;">No</td></tr></tbody></table><p>A worker is fresh for every planned feature/target pair. Startup and compilation can be measured deliberately, but controller compilation, Makie, Oxygen, Pluto and VS Code never leak into the timed workload by accident.</p><h2 id="Choose-what-to-measure" tabindex="-1">Choose what to measure <a class="header-anchor" href="#Choose-what-to-measure" aria-label="Permalink to &quot;Choose what to measure {#Choose-what-to-measure}&quot;">​</a></h2><h3 id="Existing-test-items" tabindex="-1">Existing test items <a class="header-anchor" href="#Existing-test-items" aria-label="Permalink to &quot;Existing test items {#Existing-test-items}&quot;">​</a></h3><p>Load PerfChecker and TestItemRunner, then call <code>run_testitems(pwd())</code> from your package root in its prepared test environment. This reuses its <code>@testitem</code> declarations. No generated suite is required; the <a href="./first-check">first-result tutorial</a> shows selection and result inspection.</p><h3 id="Direct-@check" tabindex="-1">Direct <code>@check</code> <a class="header-anchor" href="#Direct-@check" aria-label="Permalink to &quot;Direct `@check` {#Direct-@check}&quot;">​</a></h3><p><code>@check</code> is the compact API for a single experiment. <code>PerfConfig</code> validates the configuration before processes start, and the legacy <code>Dict</code> form remains supported. A preparation block creates the input; a second block contains the operation to measure. For example, import a bibliography during preparation, then time only its export. The <a href="./../reference/api">Julia API</a> documents the macro and its configuration. The <a href="./../tutorials/quick-tour">short Bibliography tutorial</a> provides a complete operation benchmark through the supplied suite.</p><h3 id="Feature-suites" tabindex="-1">Feature suites <a class="header-anchor" href="#Feature-suites" aria-label="Permalink to &quot;Feature suites {#Feature-suites}&quot;">​</a></h3><p><code>SoftwareSuite</code> describes a repeatable set of experiments: which operations, inputs, collectors and versions to use. For example, compare Bibliography export time and allocations across nine releases with the same input. It produces a plan and saved results. Define one when that additional configuration is useful; it is not something to install before measuring an item or using <code>@check</code>.</p><h2 id="Save-a-result-and-reopen-it" tabindex="-1">Save a result and reopen it <a class="header-anchor" href="#Save-a-result-and-reopen-it" aria-label="Permalink to &quot;Save a result and reopen it {#Save-a-result-and-reopen-it}&quot;">​</a></h2><p>The saved result contains your measurements, the code version, the Julia runtime and the measurement settings. You can reopen it in another interface without running the benchmark again. Its plots display those saved values.</p><p>You will mainly work with a <strong>plan</strong> (the selected checks), <strong>progress</strong> (what is running), a <strong>saved run</strong> (measurements and context) and <strong>plots</strong> (views of those measurements). The interfaces handle their file formats for you.</p><p>If you write a tool that reads the JSON files directly, see the <a href="./../reference/run-bundles">format reference</a>. It explains identifiers such as <code>schema_version</code>, which tell software how to read a file and do not affect which tests you select.</p><h2 id="What-to-read-next" tabindex="-1">What to read next <a class="header-anchor" href="#What-to-read-next" aria-label="Permalink to &quot;What to read next {#What-to-read-next}&quot;">​</a></h2><ul><li><p><a href="./installation">Install PerfChecker</a>.</p></li><li><p>Follow the <a href="./../tutorials/quick-tour">short Bibliography tutorial</a>.</p></li><li><p>Measure <a href="./first-check">your first test item</a>.</p></li><li><p>Understand <a href="./../suites-and-comparisons">suites and comparisons</a>.</p></li><li><p>Browse the <a href="./../reference/checks">measurement catalog</a>.</p></li><li><p>Choose an <a href="./../interfaces/packages">interface</a>.</p></li></ul>',24)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
